     SUM(NVL(th_qty,0)) AS BILL_QTY,
     -1*SUM(NVL(th_rev,0)) AS SALE_REV,
     COD_DEST4 AS COD_DEST4,
     D_MARKET_PNT,
     MODEL_NAME,
     COALESCE(D_ECOM_BU, 'ZZZZ') AS D_ECOM_BU,
