-- DWD_CIS提货明细表下沉收入处理明细

SELECT
     NEWID() AS OID,
     P_SCENARIO AS COD_SCENARIO,
     P_PERIODO AS COD_PERIODO,
     COMPANY_CODE AS COD_AZIENDA,
     'S600100AD' AS COD_CONTO,
     CUST_CODE,
     CUST_NAME,
     MATERIAL_CODE,
     MATERIAL_NAME,
     'ZZZZ' AS COD_DEST1,
     --PROFITCENTER_CODE AS COD_DEST2,
     NVL(LTRIM(PROFITCENTER_CODE,0),'ZZZZ') AS COD_DEST2,
     '020_ON_003' AS D_ONOFFLINE,
     --EDIT BY LC 260403 取值从空修改为MODEL_CODE
     MODEL_CODE AS SALE_MODEL_CODE,
     MODEL_CODE AS MODEL_CODE,
     material_pricing_group_code AS D_PRC_GRP,
     'CNY' AS COD_VALUTA,
     'REV_CIS' AS SRC_DETAIL,
     SESSION_USER AS USERUPD,
     SYSDATE AS DATEUPD,
     'CPM_SP_D2M_REV_M' AS PROVENIENZA,
     SUM(sales_qty) AS BILL_QTY,
     SUM(sales_qty) AS SHIP_QTY,
     sum(sales_qty) AS ORDER_QTY,
     (SUM((rev_sale_amt))/1.13) AS SALE_REV,
     1 AS EXCHANGE_RATE,
     BRAND_CODE AS COD_DEST4,
     NVL(spec_section_code,'ZZZZ') AS D_SPEC_SEC,
     NVL(product_shape_type_code,'ZZZZ') AS D_PRO_TYPE_S,
     'ZZZZ' AS D_PRO_SSER,
     'ZZZZ' AS D_QUA_METHOD,
     NVL(product_stage_code,'ZZZZ') AS D_PRO_STAGE,
     NVL(price_range_code,'ZZZZ') AS D_PRI_RANGE,
     NVL(product_series_code,'ZZZZ') AS D_PRO_SERIES,
     'ZZZZ' AS D_MARKET_PNT,
     NVL(tech_type_code,'ZZZZ') AS D_TECH_TYPE,
     'ZZZZ' AS D_PRO_CLASS,
     'ZZZZ' AS D_MODEL_LCA,
     'ZZZZ' AS D_PRO_TYPE,
     'ZZZZ' AS CREDIT_LEVEL_NAME,
     'ZZZZ' AS CUST_NATURE_NAME,
     --EDIT BY LC 260403 取值从空修改为MODEL_CODE
     MODEL_CODE AS SALE_MODEL_NAME,
     MODEL_CODE AS MODEL_NAME,
     'ZZZZ' AS D_CNL_C_TYPE,
     'ZZZZ' AS D_IND_C_TYPE,
     'ZZZZ' AS D_ECOM_BU,
     'ZZZZ' AS D_SALE_DEPT,
     bus_range_code AS COD_DEST3,
     is_miniled_code AS IS_MINILED_CODE,
     'REV_01_202' AS D_BU_TRAN,--单体收入成本表-共线型号下沉还原调整
      MATERIAL_GROUP_NAME
    FROM  TGK_FIMA_HISENSE.dwd_fi_mr_rev_cis_mi
WHERE 1=P_ORG_FLAG
  AND DT_MONTH = V_YEARMONTH
  AND COMPANY_CODE IN (SELECT ELEM FROM SESSION_AZIENDA_LIST WHERE SESSION_ID = V_SESSION_ID)
  --AND INSTR(V_AZIENDA, COMPANY_CODE) > 0
  AND coproduction_flag ='Y'
GROUP BY
     COMPANY_CODE ,
     CUST_CODE,
     CUST_NAME,
     MATERIAL_CODE,
     MATERIAL_NAME,
     --PROFITCENTER_CODE AS COD_DEST2,
     NVL(LTRIM(PROFITCENTER_CODE,0),'ZZZZ'),
     material_pricing_group_code,
     BRAND_CODE,
     NVL(spec_section_code,'ZZZZ'),
     NVL(product_shape_type_code,'ZZZZ'),
     NVL(product_stage_code,'ZZZZ'),
     NVL(price_range_code,'ZZZZ'),
     NVL(product_series_code,'ZZZZ'),
     NVL(tech_type_code,'ZZZZ'),
     bus_range_code,
     is_miniled_code,
     MATERIAL_GROUP_NAME,
     MODEL_CODE
HAVING SUM(COALESCE(rev_sale_amt,0))/1.13 <>0

;
COMMIT;

