    D_PRO_SSER, -- 产品套系
    D_QUA_METHOD, -- 奥维产品四分法
    D_PRO_STAGE, -- 产品阶段
    D_PRI_RANGE, -- 价格段
    D_PRO_SERIES, -- 产品系列
    D_MARKET_PNT, -- 营销定位
    D_TECH_TYPE, -- 技术类型
    D_PRO_CLASS, -- 产品类别
    D_MODEL_LCA, -- 产品型号生命周期
    D_PRO_TYPE, -- 产品类型
    CUST_UNITY_NAME, -- 统一客户组
