     COD_VALUTA,
     COD_VALUTA_ORIGINARIA,
     SRC_DETAIL||'_LM',
     COD_DEST4,
     D_SPEC_SEC,
     D_PRO_TYPE_S,
     D_PRO_SSER,
     D_QUA_METHOD,
     D_PRO_STAGE,
     D_PRI_RANGE,
     D_PRO_SERIES,
     D_MARKET_PNT,
     D_TECH_TYPE,
     D_PRO_CLASS,
     D_MODEL_LCA,
     D_PRO_TYPE,
