     CREDIT_LEVEL_NAME,
     CUST_NATURE_NAME,
     CUST_TYPE_NAME,
     SHOP_NAME,
     SALE_MODEL_NAME,
     MODEL_NAME,
     D_CNL_C_TYPE,
     D_IND_C_TYPE,
     D_ECOM_BU,
     D_SALE_DEPT,
     COD_DEST3,
     AGENCY_CODE,
     AGENCY_NAME,
     IS_MINILED_CODE,
     D_BU_TRAN, -- 事业部内外标识
     CUSTOMER_MODEL, -- 客户型号
     ORDER_TYPE_CODE,
     zcalasset,
     CN_CLASS_MARK_CODE,
     CN_CLASS_MARK_NAME,
     SALE_CERT_TYPE,
     D_ADJ_TYPE,  --调整类型
     MATERIAL_GROUP_NAME,
     maktx_s810
HAVING SUM(NVL(SALE_COGS,0)) <> 0
;

