 WHERE EXISTS (SELECT 1
                             FROM SESSION_AZIENDA_LIST
                            WHERE SESSION_ID = V_SESSION_ID
                              AND (ELEM LIKE '17%' OR ELEM = '6240')
                              AND ELEM = BUKRS)
                              ;
