INSERT /*+ PARALLEL(2) */   INTO AW_MR9_REVM01_000001_TEMP(
  OID,
  COD_SCENARIO, -- 场景
  COD_PERIODO, -- 期间
  COD_AZIENDA, -- 公司
  COD_CONTO, -- 科目
  CUST_CODE, -- 客商
  CUST_NAME, -- 客商描述
  MATERIAL_CODE, -- 物料
  MATERIAL_NAME, -- 物料描述
  COD_DEST2, -- 产品线
  D_CHANNEL, -- 销售渠道（公司三级分类）
  D_MODE, -- 销售模式
  D_ONOFFLINE, -- 线上线下
  CUST_UNITY_NAME, -- 统一客户组
  CREDIT_LEVEL_NAME, -- 信用等级
  CUST_NATURE_NAME, -- 单位性质
  CUST_TYPE_NAME, -- 客户类型
  SRC_SYSTEM, -- 源系统
  SRC_DETAIL, -- 来源
  USERUPD, -- 更新用户
  DATEUPD, -- 更新日期
  PROVENIENZA, -- 来源系统
  POLICY_AMT, -- 政策金额
  D_POL_CLASS --政策二级分类
  ,COD_DEST3
  ,d_Sale_Dept
  ,cod_dest1
  ,COD_AZI_CTP
  ,cod_dest4 --品牌
  ,MATERIAL_GROUP_CODE
  ,MATERIAL_GROUP_NAME
  ,D_MARKET_PNT
  ,D_PRO_SSER
  ,D_SPEC_SEC
  ,D_PRO_TYPE_S
  ,D_PRO_STAGE
  ,D_PRI_RANGE
  ,D_PRO_SERIES
  ,D_TECH_TYPE
  ,D_PRO_CLASS
  ,D_MODEL_LCA
  ,SALE_MODEL_CODE
  ,SALE_MODEL_NAME
  ,MODEL_CODE
  ,MODEL_NAME
  ,IS_SMALL_B
  ,CN_CLASS_MARK_CODE
  ,CN_CLASS_MARK_NAME
  ,D_ECOM_BU
  ,D_OPER_TYPE
  ,D_MINILED-- MiniLED类型

)
SELECT
    NEWID() AS OID,
    P_SCENARIO AS COD_SCENARIO,
    P_PERIODO AS COD_PERIODO,
    COALESCE(COMPANY_CODE, 'ZZZZ') AS COD_AZIENDA,
    'S6001G5' AS COD_CONTO,
    CUST_CODE,
    CUST_NAME,
    MATERIAL_CODE,
    MATERIAL_NAME,
    NVL(LTRIM(profitcenter_code,0),'ZZZZ') AS COD_DEST2,
    COALESCE(channel_l3_code, 'ZZZZ') AS D_CHANNEL,
    COALESCE(marketing_mode_code, 'ZZZZ') AS D_MODE,
    COALESCE(ONOFFLINE_CODE, 'ZZZZ') AS D_ONOFFLINE,
    CUST_UNITY_NAME,
    CREDIT_LEVEL_NAME,
    CUST_NATURE_NAME,
    CUST_TYPE_NAME,
    SYSTEM_SRC,
    ODS_SRC AS SRC_DETAIL,
    SESSION_USER AS USERUPD,
    SYSDATE AS DATEUPD,
    'CPM_SP_D2M_REV_M' AS PROVENIENZA,
    SUM(NVL(PRIZE_AMT,0) / NULLIF((1 + NVL(tax_rate,0)), 0)) AS POLICY_AMT,
    policy_l2_type_code AS D_POL_CLASS,
    bus_range_code AS COD_DEST3,
    marketing_dept_code AS d_Sale_Dept,
    'ZZZZ' as cod_dest1,
    cp_company_code as COD_AZI_CTP,
    'ZZZZ' AS cod_dest4, --品牌
    product_line_code MATERIAL_GROUP_CODE,
    product_line_NAME MATERIAL_GROUP_CODE,
   market_pnt_code AS  D_MARKET_PNT  , --  营销定位
   product_sale_series_code  AS  D_PRO_SSER  , --  产品套系
   spec_section_code AS  D_SPEC_SEC  , --  规格段
   product_shape_type_code AS  D_PRO_TYPE_S  , --  产品形态分类
   product_stage_code  AS  D_PRO_STAGE , --  产品阶段
   price_range_code  AS  D_PRI_RANGE , --  价格段
   product_series_code AS  D_PRO_SERIES  , --  产品系列
   tech_type_code  AS  D_TECH_TYPE , --  技术类型
   product_small_class_code  AS  D_PRO_CLASS , --  产品类别
   model_lca_code  AS  D_MODEL_LCA , --  产品型号生命周期
   sale_model_code AS  SALE_MODEL_CODE , --  销售型号
   sale_model_name AS  SALE_MODEL_NAME , --  销售型号描述
   model_code  AS  MODEL_CODE  , --  产品型号
   model_name  AS  MODEL_NAME  ,  --  产品型号描述
    IS_SMALL_B AS IS_SMALL_B,
   CN_CLASS_MARK_CODE AS CN_CLASS_MARK_CODE,
   CN_CLASS_MARK_NAME AS CN_CLASS_MARK_NAME,
   COMM_BU_CODE AS D_ECOM_BU,
   CASE WHEN IS_SMALL_B = '1' THEN 'OPTY021' ELSE '' END as D_OPER_TYPE
   ,miniled_type_code AS D_MINILED-- MiniLED类型

FROM tgk_fima_dev.dwd_fi_mr_rev_acct_msum_mi
WHERE 1=P_ORG_FLAG
  AND dt_month = V_YEARMONTH
  AND COMPANY_CODE IN (SELECT ELEM FROM SESSION_AZIENDA_LIST WHERE SESSION_ID = V_SESSION_ID)
  --AND INSTR(V_AZIENDA, COMPANY_CODE) > 0
  AND NOT (COMPANY_CODE='6515' AND SUBSTR(dt_month, 1, 4)='2026' AND SUBSTR(dt_month, 5, 2) <='02')
GROUP BY
    COALESCE(COMPANY_CODE, 'ZZZZ') ,
    CUST_CODE,
    CUST_NAME,
    MATERIAL_CODE,
    MATERIAL_NAME,
    NVL(LTRIM(profitcenter_code,0),'ZZZZ') ,
    COALESCE(channel_l3_code, 'ZZZZ') ,
    COALESCE(marketing_mode_code, 'ZZZZ') ,
    COALESCE(ONOFFLINE_CODE, 'ZZZZ') ,
    CUST_UNITY_NAME,
    CREDIT_LEVEL_NAME,
    CUST_NATURE_NAME,
    CUST_TYPE_NAME,
    SYSTEM_SRC,
    ODS_SRC ,
    policy_l2_type_code ,
    bus_range_code ,
    marketing_dept_code ,
    cp_company_code
    ,product_line_code,
    product_line_NAME
    ,market_pnt_code
    ,product_sale_series_code
    ,spec_section_code
    ,product_shape_type_code
    ,product_stage_code
    ,price_range_code
    ,product_series_code
    ,tech_type_code
    ,product_small_class_code
    ,model_lca_code
    ,sale_model_code
    ,sale_model_name
    ,model_code
    ,model_name
    ,IS_SMALL_B
   ,CN_CLASS_MARK_CODE
   ,CN_CLASS_MARK_NAME
   ,COMM_BU_CODE
   ,CASE WHEN IS_SMALL_B = '1' THEN 'OPTY021' ELSE '' END
   ,miniled_type_code -- MiniLED类型
   having SUM(NVL(PRIZE_AMT,0) / NULLIF((1 + NVL(tax_rate,0)), 0)) <> 0
;
COMMIT;


INSERT /*+ PARALLEL(2) */   INTO AW_MR9_REVM01_000001_TEMP(
  OID,
  COD_SCENARIO, -- 场景
  COD_PERIODO, -- 期间
  COD_AZIENDA, -- 公司
  COD_CONTO, -- 科目
  CUST_CODE, -- 客商
  CUST_NAME, -- 客商描述
  MATERIAL_CODE, -- 物料
  MATERIAL_NAME, -- 物料描述
  COD_DEST2, -- 产品线
  D_CHANNEL, -- 销售渠道（公司三级分类）
  D_MODE, -- 销售模式
  D_ONOFFLINE, -- 线上线下
  CUST_UNITY_NAME, -- 统一客户组
  CREDIT_LEVEL_NAME, -- 信用等级
  CUST_NATURE_NAME, -- 单位性质
  CUST_TYPE_NAME, -- 客户类型
  SRC_SYSTEM, -- 源系统
  SRC_DETAIL, -- 来源
  USERUPD, -- 更新用户
  DATEUPD, -- 更新日期
  PROVENIENZA, -- 来源系统
  POLICY_AMT, -- 政策金额
  D_POL_CLASS --政策二级分类
  ,COD_DEST3
  ,d_Sale_Dept
  ,cod_dest1
  ,COD_AZI_CTP
  ,cod_dest4 --品牌
  ,D_MARKET_PNT
  ,D_PRO_SSER
  ,D_SPEC_SEC
  ,D_PRO_TYPE_S
  ,D_PRO_STAGE
  ,D_PRI_RANGE
  ,D_PRO_SERIES
  ,D_TECH_TYPE
  ,D_PRO_CLASS
  ,D_MODEL_LCA
  ,SALE_MODEL_CODE
  ,SALE_MODEL_NAME
  ,MODEL_CODE
  ,MODEL_NAME
  ,D_MINILED-- MiniLED类型
)
--日立政策数据来源于DWD_FI_MR_REV_ACCT_PA_MI-政策计提数据-日立专用，所以需要新增加该段逻辑处理
SELECT
    NEWID() AS OID,
    P_SCENARIO AS COD_SCENARIO,
    P_PERIODO AS COD_PERIODO,
    COALESCE(COMPANY_CODE, 'ZZZZ') AS COD_AZIENDA,
    'S6001G5' AS COD_CONTO,
    CUST_CODE,
    CUST_NAME,
    MATERIAL_CODE,
    MATERIAL_NAME,
    NVL(LTRIM(profitcenter_code,0),'ZZZZ') AS COD_DEST2,
    COALESCE(channel_l3_code, 'ZZZZ') AS D_CHANNEL,
    COALESCE(marketing_mode_code, 'ZZZZ') AS D_MODE,
    COALESCE(ONOFFLINE_CODE, 'ZZZZ') AS D_ONOFFLINE,
    CUST_UNITY_NAME,
    CREDIT_LEVEL_NAME,
    CUST_NATURE_NAME,
    CUST_TYPE_NAME,
    SYSTEM_SRC,
    ODS_SRC AS SRC_DETAIL,
    SESSION_USER AS USERUPD,
    SYSDATE AS DATEUPD,
    'CPM_SP_D2M_REV_M' AS PROVENIENZA,
     SUM(CASE WHEN system_src = 'SMS' THEN NVL(prize_amt,0) - NVL(gfcfy_amount,0) + NVL(gfcfl_amount,0)
     ELSE NVL(PRIZE_AMT,0) / NULLIF((1 + NVL(tax_rate,0)), 0)
  END) AS POLICY_AMT,
    policy_l2_type_code AS D_POL_CLASS,
     COALESCE(bus_range_code, 'ZZZZ') AS COD_DEST3,
    marketing_dept_code AS marketing_dept_code,
     COALESCE(cost_center_code, 'ZZZZ') as cod_dest1,
    cp_company_code as COD_AZI_CTP,
    COALESCE(BRAND_CODE, 'ZZZZ') AS COD_DEST4,
  market_pnt_code AS  D_MARKET_PNT  , --  营销定位
  product_sale_series_code  AS  D_PRO_SSER  , --  产品套系
  spec_section_code AS  D_SPEC_SEC  , --  规格段
  product_shape_type_code AS  D_PRO_TYPE_S  , --  产品形态分类
  product_stage_code  AS  D_PRO_STAGE , --  产品阶段
  price_range_code  AS  D_PRI_RANGE , --  价格段
  product_series_code AS  D_PRO_SERIES  , --  产品系列
  tech_type_code  AS  D_TECH_TYPE , --  技术类型
  product_small_class_code  AS  D_PRO_CLASS , --  产品类别
  model_lca_code  AS  D_MODEL_LCA , --  产品型号生命周期
  sale_model_code AS  SALE_MODEL_CODE , --  销售型号
  sale_model_name AS  SALE_MODEL_NAME , --  销售型号描述
  model_code  AS  MODEL_CODE  , --  产品型号
  model_name  AS  MODEL_NAME    --  产品型号描述
  ,miniled_type_code AS D_MINILED-- MiniLED类型
 FROM tgk_fima_dev.DWD_FI_MR_REV_ACCT_PA_MI
WHERE 1=P_ORG_FLAG
  AND DT_MONTH = V_YEARMONTH
  AND COMPANY_CODE IN (SELECT ELEM FROM SESSION_AZIENDA_LIST WHERE SESSION_ID = V_SESSION_ID)
  --AND INSTR(V_AZIENDA, COMPANY_CODE) > 0
GROUP BY
    COALESCE(COMPANY_CODE, 'ZZZZ') ,
    CUST_CODE,
    CUST_NAME,
    MATERIAL_CODE,
    MATERIAL_NAME,
    NVL(LTRIM(profitcenter_code,0),'ZZZZ') ,
    COALESCE(channel_l3_code, 'ZZZZ') ,
    COALESCE(marketing_mode_code, 'ZZZZ') ,
    COALESCE(ONOFFLINE_CODE, 'ZZZZ') ,
    CUST_UNITY_NAME,
    CREDIT_LEVEL_NAME,
    CUST_NATURE_NAME,
    CUST_TYPE_NAME,
    SYSTEM_SRC,
    ODS_SRC ,
    policy_l2_type_code ,
    COALESCE(bus_range_code, 'ZZZZ'),
    marketing_dept_code,
    COALESCE(cost_center_code, 'ZZZZ'),
    cp_company_code,
    COALESCE(BRAND_CODE, 'ZZZZ')
  ,market_pnt_code
  ,product_sale_series_code
  ,spec_section_code
  ,product_shape_type_code
  ,product_stage_code
  ,price_range_code
  ,product_series_code
  ,tech_type_code
  ,product_small_class_code
  ,model_lca_code
  ,sale_model_code
  ,sale_model_name
  ,model_code
  ,model_name
  ,miniled_type_code
HAVING  SUM(CASE WHEN system_src = 'SMS' THEN NVL(prize_amt,0) - NVL(gfcfy_amount,0) + NVL(gfcfl_amount,0)
     ELSE NVL(PRIZE_AMT,0) / NULLIF((1 + NVL(tax_rate,0)), 0)
  END) <> 0

UNION ALL
--日立管法差数据进政策金额字段

SELECT
    NEWID() AS OID,
    P_SCENARIO AS COD_SCENARIO,
    P_PERIODO AS COD_PERIODO,
    COALESCE(COMPANY_CODE, 'ZZZZ') AS COD_AZIENDA,
    CASE WHEN FLAG = 'GFCFY' THEN 'S6001G2' WHEN FLAG = 'GFCFL' THEN 'S6001G3' END AS COD_CONTO,
    CUST_CODE,
    CUST_NAME,
    MATERIAL_CODE,
    MATERIAL_NAME,
    NVL(LTRIM(profitcenter_code,0),'ZZZZ') AS COD_DEST2,
    COALESCE(channel_l3_code, 'ZZZZ') AS D_CHANNEL,
    COALESCE(marketing_mode_code, 'ZZZZ') AS D_MODE,
    COALESCE(ONOFFLINE_CODE, 'ZZZZ') AS D_ONOFFLINE,
    CUST_UNITY_NAME,
    CREDIT_LEVEL_NAME,
    CUST_NATURE_NAME,
    CUST_TYPE_NAME,
    SYSTEM_SRC,
    ODS_SRC AS SRC_DETAIL,
    SESSION_USER AS USERUPD,
    SYSDATE AS DATEUPD,
    'CPM_SP_D2M_REV_M' AS PROVENIENZA,
    SUM(NVL(IMPORTO,0)) AS POLICY_AMT,
    policy_l2_type_code as D_POL_CLASS,
    COALESCE(bus_range_code, 'ZZZZ') AS COD_DEST3,
    marketing_dept_code AS marketing_dept_code,
    COALESCE(cost_center_code, 'ZZZZ') as cod_dest1,
    cp_company_code as COD_AZI_CTP,
    COALESCE(BRAND_CODE, 'ZZZZ') AS COD_DEST4,
  market_pnt_code AS  D_MARKET_PNT  , --  营销定位
  product_sale_series_code  AS  D_PRO_SSER  , --  产品套系
  spec_section_code AS  D_SPEC_SEC  , --  规格段
  product_shape_type_code AS  D_PRO_TYPE_S  , --  产品形态分类
  product_stage_code  AS  D_PRO_STAGE , --  产品阶段
  price_range_code  AS  D_PRI_RANGE , --  价格段
  product_series_code AS  D_PRO_SERIES  , --  产品系列
  tech_type_code  AS  D_TECH_TYPE , --  技术类型
  product_small_class_code  AS  D_PRO_CLASS , --  产品类别
  model_lca_code  AS  D_MODEL_LCA , --  产品型号生命周期
  sale_model_code AS  SALE_MODEL_CODE , --  销售型号
  sale_model_name AS  SALE_MODEL_NAME , --  销售型号描述
  model_code  AS  MODEL_CODE  , --  产品型号
  model_name  AS  MODEL_NAME    --  产品型号描述
  ,miniled_type_code AS D_MINILED-- MiniLED类型
FROM(
    SELECT 'GFCFY' AS FLAG,YEAR,MONTH,COMPANY_CODE,CUST_CODE,CUST_NAME,MATERIAL_CODE,MATERIAL_NAME
      ,PROFITCENTER_CODE,CHANNEL_L3_CODE,MARKETING_MODE_CODE,ONOFFLINE_CODE,CUST_UNITY_NAME,CREDIT_LEVEL_NAME,
      CUST_NATURE_NAME,CUST_TYPE_NAME,
      SYSTEM_SRC,ODS_SRC,policy_l2_type_code,bus_range_code,
       marketing_dept_code,
       cost_center_code,
       cp_company_code,
       BRAND_CODE
      ,GFCFY_AMOUNT AS IMPORTO --价差转费用
    ,market_pnt_code
    ,product_sale_series_code
    ,spec_section_code
    ,product_shape_type_code
    ,product_stage_code
    ,price_range_code
    ,product_series_code
    ,tech_type_code
    ,product_small_class_code
    ,model_lca_code
    ,sale_model_code
    ,sale_model_name
    ,model_code
    ,model_name
  ,miniled_type_code
    FROM tgk_fima_dev.DWD_FI_MR_REV_ACCT_PA_MI MI
    WHERE 1=P_ORG_FLAG
    AND DT_MONTH = V_YEARMONTH
    AND COMPANY_CODE IN (SELECT ELEM FROM SESSION_AZIENDA_LIST WHERE SESSION_ID = V_SESSION_ID)
    --AND INSTR(V_AZIENDA, COMPANY_CODE) > 0
    AND ODS_SRC IN ('POLICY_YT')
    AND GFCFY_AMOUNT IS NOT NULL

    UNION ALL
    SELECT 'GFCFL' AS FLAG,YEAR,MONTH,COMPANY_CODE,CUST_CODE,CUST_NAME,MATERIAL_CODE,MATERIAL_NAME
      ,PROFITCENTER_CODE,CHANNEL_L3_CODE,MARKETING_MODE_CODE,ONOFFLINE_CODE,CUST_UNITY_NAME,CREDIT_LEVEL_NAME,
      CUST_NATURE_NAME,CUST_TYPE_NAME,SYSTEM_SRC,
      ODS_SRC,policy_l2_type_code,bus_range_code,
       marketing_dept_code,
       cost_center_code,
       cp_company_code,
       BRAND_CODE
      ,0-NVL(GFCFL_AMOUNT,0) AS IMPORTO --费用转价差
    ,market_pnt_code
    ,product_sale_series_code
    ,spec_section_code
    ,product_shape_type_code
    ,product_stage_code
    ,price_range_code
    ,product_series_code
    ,tech_type_code
    ,product_small_class_code
    ,model_lca_code
    ,sale_model_code
    ,sale_model_name
    ,model_code
    ,model_name
  ,miniled_type_code
    FROM tgk_fima_dev.DWD_FI_MR_REV_ACCT_PA_MI MI
    WHERE 1=P_ORG_FLAG
    AND DT_MONTH = V_YEARMONTH
    AND COMPANY_CODE IN (SELECT ELEM FROM SESSION_AZIENDA_LIST WHERE SESSION_ID = V_SESSION_ID)
    --AND INSTR(V_AZIENDA, COMPANY_CODE) > 0
    AND ODS_SRC IN ('POLICY_YT')
    AND GFCFL_AMOUNT IS NOT NULL
  )T
GROUP BY
    COALESCE(COMPANY_CODE, 'ZZZZ') ,
    CASE WHEN FLAG = 'GFCFY' THEN 'S6001G2' WHEN FLAG = 'GFCFL' THEN 'S6001G3' END ,
    CUST_CODE,
    CUST_NAME,
    MATERIAL_CODE,
    MATERIAL_NAME,
    NVL(LTRIM(profitcenter_code,0),'ZZZZ') ,
    COALESCE(channel_l3_code, 'ZZZZ') ,
    COALESCE(marketing_mode_code, 'ZZZZ') ,
    COALESCE(ONOFFLINE_CODE, 'ZZZZ') ,
    CUST_UNITY_NAME,
    CREDIT_LEVEL_NAME,
    CUST_NATURE_NAME,
    CUST_TYPE_NAME,
    SYSTEM_SRC,
    ODS_SRC ,
    policy_l2_type_code ,
    COALESCE(bus_range_code, 'ZZZZ'),
    marketing_dept_code,
    COALESCE(cost_center_code, 'ZZZZ'),
    cp_company_code,
    COALESCE(BRAND_CODE, 'ZZZZ')
  ,market_pnt_code
  ,product_sale_series_code
  ,spec_section_code
  ,product_shape_type_code
  ,product_stage_code
  ,price_range_code
  ,product_series_code
  ,tech_type_code
  ,product_small_class_code
  ,model_lca_code
  ,sale_model_code
  ,sale_model_name
  ,model_code
  ,model_name
  ,miniled_type_code-- MiniLED类型
HAVING SUM(NVL(IMPORTO,0)) <> 0
;
COMMIT;


INSERT /*+ PARALLEL(2) */   INTO AW_MR9_REVM01_000001_TEMP(
  OID,
  COD_SCENARIO, -- 场景
  COD_PERIODO, -- 期间
  COD_AZIENDA, -- 公司
  COD_CONTO, -- 科目
  CUST_CODE, -- 客商
  CUST_NAME, -- 客商描述
  MATERIAL_CODE, -- 物料
  MATERIAL_NAME, -- 物料描述
  COD_DEST2, -- 产品线
  D_CHANNEL, -- 销售渠道（公司三级分类）
  D_ONOFFLINE, -- 线上线下
  SRC_DETAIL, -- 来源
  USERUPD, -- 更新用户
  DATEUPD, -- 更新日期
  PROVENIENZA, -- 来源系统
  POLICY_AMT, -- 政策金额
  COD_DEST3
  ,d_Sale_Dept
  ,COD_CATEGORIA
  ,cod_dest1
  ,COD_AZI_CTP
  ,cod_dest4 --品牌
  ,D_MARKET_PNT
  ,D_PRO_SSER
  ,D_SPEC_SEC
  ,D_PRO_TYPE_S
  ,D_PRO_STAGE
  ,D_PRI_RANGE
  ,D_PRO_SERIES
  ,D_TECH_TYPE
  ,D_PRO_CLASS
  ,D_MODEL_LCA
  ,MODEL_CODE
  ,MODEL_NAME
  ,CN_CLASS_MARK_CODE
  ,CN_CLASS_MARK_NAME
  ,D_ADJ_TYPE
  ,D_ECOM_BU
)
SELECT
    NEWID() AS OID,
    P_SCENARIO AS COD_SCENARIO,
    P_PERIODO AS COD_PERIODO,
    COD_AZIENDA,
    'S6001G5AD' AS COD_CONTO,--政策计提-TA手工调整
    CUST_CODE,
    CUST_NAME,
    MATERIAL_CODE,
    MATERIAL_NAME,
    COD_DEST2,
    NVL(D_CHANNEL,'ZZZZ') AS D_CHANNEL,
    D_ONOFFLINE,
    'ADJM01' AS SRC_DETAIL,
    SESSION_USER AS USERUPD,
    SYSDATE AS DATEUPD,
    'CPM_SP_D2M_REV_M' AS PROVENIENZA,
    SUM(POLICY_AMT) AS POLICY_AMT,
    COD_DEST3,
    D_SALE_DEPT,
    'GA00_BF' AS COD_CATEGORIA,
     CASE WHEN COD_AZIENDA LIKE '17%' OR COD_AZIENDA = '6240' THEN COD_DEST1 ELSE 'ZZZZ' END AS COD_DEST1,
    COD_AZI_CTP as COD_AZI_CTP,
    NVL(COD_DEST4,'ZZZZ') AS COD_DEST4,
  D_MARKET_PNT  , --  营销定位
  D_PRO_SSER  , --  产品套系
  D_SPEC_SEC  , --  规格段
  D_PRO_TYPE_S  , --  产品形态分类
  D_PRO_STAGE , --  产品阶段
  D_PRI_RANGE , --  价格段
  D_PRO_SERIES  , --  产品系列
  D_TECH_TYPE , --  技术类型
  D_PRO_CLASS , --  产品类别
  D_MODEL_LCA , --  产品型号生命周期
  MODEL_CODE  , --  产品型号
  MODEL_NAME    --  产品型号描述
  ,CN_CLASS_MARK_CODE
  ,CN_CLASS_MARK_NAME
  ,D_ADJ_TYPE
  /*20260820-1 SHIQINGFENG.EX 新增政策手工调整电商BU渠道细分*/
  ,D_ECOM_BU
FROM TGK_FIMA_HISENSE.AW_MR9_ADJM01_000001
WHERE 1=1
  AND year_month = V_YEARMONTH
  AND COD_AZIENDA IN (SELECT ELEM FROM SESSION_AZIENDA_LIST WHERE SESSION_ID = V_SESSION_ID)
  --AND INSTR(V_AZIENDA, COD_AZIENDA) > 0
  --EDIT BY LC 260309 增加限制
  AND COD_CATEGORIA = 'ZFAMOUNT'
  AND COD_CONTO = 'ZAW_DWM_REV_STAN'
  AND D_ADJ_TYPE = 'REV_01_201'
GROUP BY
    CUST_CODE,
    NVL(D_CHANNEL,'ZZZZ'),
    COD_AZIENDA,
    CUST_NAME,
    MATERIAL_CODE,
    MATERIAL_NAME,
    COD_DEST2,
    D_ONOFFLINE,
    COD_DEST3,
    D_SALE_DEPT,
     CASE WHEN COD_AZIENDA LIKE '17%' OR COD_AZIENDA = '6240' THEN COD_DEST1 ELSE 'ZZZZ' END,
    COD_AZI_CTP,
  D_MARKET_PNT  , --  营销定位
  D_PRO_SSER  , --  产品套系
  D_SPEC_SEC  , --  规格段
  D_PRO_TYPE_S  , --  产品形态分类
  D_PRO_STAGE , --  产品阶段
  D_PRI_RANGE , --  价格段
  D_PRO_SERIES  , --  产品系列
  D_TECH_TYPE , --  技术类型
  D_PRO_CLASS , --  产品类别
  D_MODEL_LCA , --  产品型号生命周期
  MODEL_CODE  , --  产品型号
  MODEL_NAME ,   --  产品型号描述
  NVL(COD_DEST4,'ZZZZ')
  ,CN_CLASS_MARK_CODE
  ,CN_CLASS_MARK_NAME
  ,D_ADJ_TYPE
  ,D_ECOM_BU
HAVING SUM(POLICY_AMT) <>0
    ;

COMMIT;


