        WHERE TO_DATE(SUBSTR(TARGET.COD_SCENARIO, 1, 4) || TARGET.COD_PERIODO, 'YYYYMM')
              BETWEEN TO_DATE(VALID_FR, 'YYYYMM')
              AND TO_DATE(NVL(VALID_TO, '999912'), 'YYYYMM')
              AND ROWID = (
