                                   T.BCY_REV / NVL(CA.CAMBIO_PERIODO, 0))
                   END,
                  CASE
                       WHEN T.COD_AZIENDA IN (
                                SELECT DISTINCT ELEM
                                  FROM SESSION_V_REF_AZIENDA
                                 WHERE SESSION_ID = V_SESSION_ID
                                   AND NODE = '020'
                                   AND HIE  = '10'
                            ) THEN T.BCY_COGS
                       ELSE DECODE(NVL(CA.CAMBIO_PERIODO, 0),
