  , D_PRO_CLASS
  , D_DATA_BLOCK
  , '100604001' AS D_DIFF_TYPE
  , MATERIAL_CODE
  , MATERIAL_NAME
  , COD_DEST2
  , COD_DEST4
  , D_MARKET_PNT
  , D_PRO_SSER
  , D_SPEC_SEC
  , D_PRO_TYPE_S
  , D_QUA_METHOD
  , D_PRO_STAGE
  , D_PRI_RANGE
  , D_PRO_SERIES
  , D_TECH_TYPE
  , D_MODEL_LCA
  , D_PRO_TYPE
  , SALE_MODEL_NAME
  , D_POL_CLASS
  , MODEL_NAME
  , CUST_CODE
  , MODEL_CODE
  , SALE_MODEL_CODE
  , CUST_NAME
  , D_CHANNEL
  , D_MODE
